// === Normalize Excel rows from Thai headers to standard fields ===

// ---- universal space cleaner ----
function cleanSpaces(s) {
  return String(s ?? '')
    // ลบช่องว่างแปลกๆ (non-breaking, zero-width, full-width, etc.)
    .replace(/[\u00A0\u1680\u2000-\u200D\u202F\u205F\u3000\uFEFF]/g, ' ')
    // แปลง tab/newline ให้เป็น space ปกติ
    .replace(/[\t\r\n]+/g, ' ')
    // รวม space ซ้ำ
    .replace(/\s+/g, ' ')
    .trim();
}

function onlyDigits(s) {
  return String(s ?? '').replace(/\D/g, '');
}

// แปลงเลขผู้เสียภาษีให้เป็น string ตัวเลขล้วน (ถ้าสั้นกว่า 13 จะ pad)
function normVatId(v) {
  if (v === null || v === undefined || v === '') return null;
  let s = onlyDigits(v);
  if (!s) return null;

  // เคสหน่วยงานรัฐที่เป็น 0/0000000000000 จะจัดการทีหลังก็ได้
  if (/^0+$/.test(s)) return '0';

  if (s.length < 13) {
    s = s.padStart(13, '0');
  }
  return s;
}

// แปลง branch ให้เป็น string 5 หลัก
function normBranch(b) {
  if (b === null || b === undefined) return null;
  let raw = String(b).trim();
  if (!raw) return '00000'; // ไม่มี = treat เป็นสำนักงานใหญ่ก็ได้
  if (raw === 'รวม') return '00000'; // แถวสรุป หรือรวมสาขา → ไม่ใช่ใบกำกับจริง

  let s = onlyDigits(raw);
  if (!s) return '00000';
  if (s === '0') s = '0';
  return s.padStart(5, '0');
}

// แปลงจำนวนเงินให้เป็น Number (รองรับทั้ง string/มีคอมมา)
function parseAmount(val) {
  if (val === null || val === undefined || val === '') return null;
  if (typeof val === 'number' && Number.isFinite(val)) return val;
  const normalized = String(val).replace(/[^\d.\-]/g, '');
  if (!normalized) return null;
  const n = Number(normalized);
  return Number.isNaN(n) ? null : n;
}

// normalize ชื่อบริษัท
function normalizeCompanyName(name) {
  if (!name) return null;
  let s = cleanSpaces(String(name));
  s = s.replace(/[“”"']/g, '');
  s = cleanSpaces(s);
  return s || null;
}

// === main ===
const out = [];

for (const item of items) {
  const r = item.json;

  // ---- ดึงค่าจากหัวคอลัมน์ตามไฟล์ Excel นี้ ----
  const inv      = cleanSpaces(r['เลขที่ใบกำกับภาษี'] ?? '');
  const date     = cleanSpaces(r['วันที่ใบกำกับภาษี'] ?? '');
  const ref_doc  = cleanSpaces(r['เลขที่เอกสารอ้างอิง'] ?? '');
  const doc_title = cleanSpaces(r['ประเภทใบกำกับ'] ?? '');  // << เปลี่ยนจาก 'ประเภทเอกสาร' เป็น 'ประเภทใบกำกับ'
  const contact_code = cleanSpaces(r['รหัสผู้ติดต่อ'] ?? '');
  const vname   = cleanSpaces(r['ผู้ติดต่อ'] ?? '');
  const vvat    = r['เลขทะเบียนผู้เสียภาษี'] ?? '';
  const vbr     = r['สาขา/สำนักงานใหญ่'] ?? '';
  const net     = r['รายการภาษี 7%'];
  const vat     = r['ภาษีมูลค่าเพิ่ม'];
  const grand   = r['มูลค่ารวมภาษี'];
  const status  = cleanSpaces(r['สถานะ'] ?? '');

  // ข้ามแถวที่ไม่มีข้อมูลหลัก (กันเคสว่าง/บรรทัดแปลกๆ)
  if (!inv && !vvat && !vname) {
    continue;
  }

  const vendor_name   = normalizeCompanyName(vname);
  const vendor_vat_id = normVatId(vvat);
  const vendor_branch = normBranch(vbr);

  const net_amount    = parseAmount(net);
  const vat_amount    = parseAmount(vat);
  const grand_total   = parseAmount(grand);

  out.push({
    json: {
      // key หลักที่ใช้ downstream
      invoice_number: inv,
      date_raw:       date,

      vendor_name,
      vendor_vat_id,
      vendor_branch,

      net_amount,
      vat_amount,
      grand_total,

      ref_doc:       ref_doc,      
      doc_title:     doc_title || null,
      contact_code:  contact_code,  
      status_text:   status || null
    },
    pairedItem: item.pairedItem,
  });
}

return out;

// Compare Logic (Simplified)
// Inputs:
// 1. Excel Rows (Normalized) from "Code: Normalize rows"
// 2. DB Rows (Normalized) from "Normalize DB Rows"

function sameAmount(a, b, eps = 0.01) {
  if (a == null || b == null) return false;
  const na = Number(a);
  const nb = Number(b);
  if (Number.isNaN(na) || Number.isNaN(nb)) return false;
  return Math.abs(na - nb) <= eps;
}

