// 1) Get Data
const excelItems = $items('Code: Normalize rows', 0, 0);
const excelRows  = excelItems.map(i => i.json);

const dbItems = $items('Normalize DB Rows', 0, 0);
const dbRows  = dbItems.map(i => i.json);

// 2) Build Map (DB)
const dbMap = new Map();
const dbKeySet = new Set();
const excelKeySet = new Set();

for (const row of dbRows) {
  const key = [row._norm_invoice_number, row._norm_vendor_vat_id, row._norm_vendor_branch].join('|');
  dbKeySet.add(key);
  if (!dbMap.has(key)) {
    dbMap.set(key, row);
  }
}

// 3) Pass 1: Excel -> DB
const out = [];

for (let index = 0; index < excelRows.length; index++) {
  const r = excelRows[index];

  // Excel data is already normalized by previous node, but let's be safe with keys
  // "Code: Normalize rows" outputs: invoice_number, vendor_vat_id, vendor_branch (already normalized)

  const invoice_number = r.invoice_number; 
  const vendor_vat_id  = r.vendor_vat_id;
  const vendor_branch  = r.vendor_branch;
  const vendor_name    = r.vendor_name;

  if (!invoice_number && !vendor_vat_id && !vendor_name) continue;

  const key = [invoice_number, vendor_vat_id, vendor_branch].join('|');
  excelKeySet.add(key);

  const inv = dbMap.get(key) || null;
  let all_ok = false;

  let invoice_number_status = null;
  let date_raw_status       = null;
  let vendor_name_status    = null;
  let vendor_vat_id_status  = null;
  let vendor_branch_status  = null;
  let net_amount_status     = null;
  let vat_amount_status     = null;
  let grand_total_status    = null;

  if (inv) {
    // Compare
    // Note: Excel 'invoice_number' is already normalized. DB 'inv._norm_invoice_number' is normalized.
    invoice_number_status = (invoice_number === inv._norm_invoice_number);

    // Date: Excel 'date_raw' is normalized string. DB 'date_raw' is string.
    // We might need simple trim comparison.
    date_raw_status = (cleanSpaces(r.date_raw) === cleanSpaces(inv.date_raw));

    vendor_name_status    = (vendor_name    === inv._norm_vendor_name);
    vendor_vat_id_status  = (vendor_vat_id  === inv._norm_vendor_vat_id);
    vendor_branch_status  = (vendor_branch  === inv._norm_vendor_branch);

    net_amount_status     = sameAmount(r.net_amount,  inv.net_amount);
    vat_amount_status     = sameAmount(r.vat_amount,  inv.vat_amount);
    grand_total_status    = sameAmount(r.grand_total, inv.grand_total);

    all_ok = [
      invoice_number_status, date_raw_status, vendor_name_status,
      vendor_vat_id_status, vendor_branch_status,
      net_amount_status, vat_amount_status, grand_total_status
    ].every(v => v === true);
  }

  out.push({
    json: {
      source: 'excel',
      missing_in_pdf: !inv,
      missing_in_excel: false,
      invoice_id: inv ? inv.id : null,
      invoice_number, vendor_vat_id, vendor_branch,
      invoice_number_status, date_raw_status, vendor_name_status,
      vendor_vat_id_status, vendor_branch_status,
      net_amount_status, vat_amount_status, grand_total_status,
      invoice_status: null, buyer_vat_info_status: null,
      all_ok,
    },
    pairedItem: excelItems[index]?.pairedItem,
  });
}

// 4) Pass 2: DB -> Excel
for (const db of dbRows) {
  const key = [db._norm_invoice_number, db._norm_vendor_vat_id, db._norm_vendor_branch].join('|');

  if (!excelKeySet.has(key)) {
    out.push({
      json: {
        source: 'pdf',
        missing_in_pdf: false,
        missing_in_excel: true,
        invoice_id: db.id,
        invoice_number: db._norm_invoice_number,
        vendor_vat_id:  db._norm_vendor_vat_id,
        vendor_branch:  db._norm_vendor_branch,
        invoice_number_status: null, date_raw_status: null, vendor_name_status: null,
        vendor_vat_id_status: null, vendor_branch_status: null,
        net_amount_status: null, vat_amount_status: null, grand_total_status: null,
        invoice_status: null, buyer_vat_info_status: null,
        all_ok: false,
      }
    });
  }
}

return out;

const items = $input.all();

// ดึงชื่อโฟลเดอร์สุดท้าย เช่น "/files/EXAM/" → "EXAM"
function extractFolderName(path) {
  if (!path) return "default";
  const parts = String(path).split('/');
  for (let i = parts.length - 1; i >= 0; i--) {
    if (parts[i] && parts[i].trim() !== "" && !parts[i].includes('*')) {
      return parts[i];
    }
  }
  return "default";
}

return items.map(item => {
  const body = item.json.body || {};

  // ❗ ใช้ path จาก body.schema แทน excelFolder
  const schemaPath = body.schema;        // เช่น "/files/EXAM/"

  // ดึง folder สุดท้าย → "EXAM"
  const folderName = extractFolderName(schemaPath);

  // normalize unicode
  const normalized = folderName.normalize("NFC");

  // แปลงเป็น hex 16 ตัว
  const hashedSchema = "s_" + Buffer.from(normalized).toString("hex").slice(0, 16);

  return {
    json: {
      ...item.json,
      body: {
        ...body,
        schema: hashedSchema,   // เขียนทับ schema เดิม
      },
    },
  };
});

const items = $input.all();

// update เฉพาะ items ที่มี invoice_number + vendor_vat_id + vendor_branch ครบ
return items.filter(i => {
  const j = i.json;
  return (
    j.invoice_number &&
    String(j.invoice_number).trim() !== "" &&
    j.vendor_vat_id &&
    j.vendor_branch
  );
});

// Normalize DB rows
function cleanSpaces(s) {
  return String(s ?? '')
    .replace(/[\u00A0\u1680\u2000-\u200D\u202F\u205F\u3000\uFEFF]/g, ' ')
    .replace(/[\t\r\n]+/g, ' ')
    .replace(/\s+/g, ' ')
    .trim();
}

function onlyDigits(s) {
  return String(s ?? '').replace(/\D/g, '');
}

function normVatId(v) {
  if (v == null || v === '') return null;
  let s = onlyDigits(v);
  if (!s) return null;
  if (/^0+$/.test(s)) return '0';
  return s.padStart(13, '0');
}

function normBranch(b) {
  if (b == null) return null;
  let s = onlyDigits(String(b));
  if (!s) return '00000';
  return s.padStart(5, '0');
}

function normalizeCompanyName(name) {
  if (!name) return null;
  let s = cleanSpaces(String(name));
  s = s.replace(/[“”"']/g, '');
  s = s.replace(/\u200B/g, '');
  s = s.replace(/\s+/g, '');
  return s || null;
}

const items = $input.all();
return items.map(item => {
  const row = item.json;
  return {
    json: {
      ...row,
      _norm_invoice_number: cleanSpaces(row.invoice_number),
      _norm_vendor_vat_id: normVatId(row.vendor_vat_id),
      _norm_vendor_branch: normBranch(row.vendor_branch),
      _norm_vendor_name: normalizeCompanyName(row.vendor_name)
    }
  };
});
